import React, { useState } from 'react';
import './pizza-card.css';
import { useDispatch, useSelector } from 'react-redux';
import { addItems } from '../../redux/slices/cartSlice';
import { RootState } from '../../redux/store';
import { Link } from 'react-router-dom';

interface PizzaCardProps {
  id: string;
  title: string;
  price: number;
  imageUrl: string;
  types: number[];
  sizes: number[];
}

const PizzaCard: React.FC<PizzaCardProps> = ({ id, title, price, imageUrl, types, sizes }) => {
  const [activeDough, setActiveDough] = useState<number>(types?.[0]);
  const [activeSize, setActiveSize] = useState<number>(sizes?.[0]);

  // типизация state через RootState
  const cartItem = useSelector((state: RootState) => state.cart.items.find((obj) => obj.id === id));

  const typeName = ['тонке', 'традиційне'];
  const dispatch = useDispatch();
  const addedCount = cartItem ? cartItem.count : 0;

  const onClickAdd = () => {
    const item = {
      id,
      title,
      price,
      imageUrl,
      type: typeName[activeDough],
      size: activeSize,
      types,
      sizes,
      count: 1,
    };
    dispatch(addItems(item));
  };

  const handleSelectListDough = (item: number) => {
    setActiveDough(item);
  };

  const handleSelectListSize = (item: number) => {
    setActiveSize(item);
  };

  return (
    <div className="pizza-card__wrapper">
      <Link to={`/pizza/${id}`}>
        <img src={imageUrl} alt={title} />
        <h2 className="pizza-card__title">{title}</h2>
      </Link>

      <div className="pizza-card__order">
        <ul className="pizza-card__dough-wrapper">
          {types.map((typeId) => (
            <li
              key={typeId}
              className={`pizza-card__dough ${
                activeDough === typeId ? 'pizza-card__dough--active' : ''
              }`}
              onClick={() => handleSelectListDough(typeId)}
            >
              {typeName[typeId]}
            </li>
          ))}
        </ul>

        <ul className="pizza-card__size-wrapper">
          {sizes.map((size) => (
            <li
              key={size}
              className={`pizza-card__size ${
                activeSize === size ? 'pizza-card__size--active' : ''
              }`}
              onClick={() => handleSelectListSize(size)}
            >
              {size} см.
            </li>
          ))}
        </ul>
      </div>

      <div className="pizza-card__btn-wrapper">
        <p className="card__size-price">від {price}₴</p>
        <button
          onClick={onClickAdd}
          className={`pizza-card__btn ${addedCount > 0 ? 'pizza-card__btn--active' : ''}`}
        >
          <p>+ Додати</p>
          {addedCount > 0 && <span>{addedCount}</span>}
        </button>
      </div>
    </div>
  );
};

export default PizzaCard;
