import { useState, useEffect, useRef } from 'react';
import PizzaCard from '../card/Pizza-card';
import Skeleton from '../card/skeleton';
import './pizza.css';
import Paginate from '../paginate/Paginate';
import { setPageCount, setFilters } from '../../redux/slices/filterSlice';
import { useDispatch, useSelector } from 'react-redux';
import qs from 'qs';
import { useNavigate } from 'react-router-dom';
import { sortOptions } from '../nav/Nav';
import { fetchPizzas } from '../../redux/slices/pizzaSlice';
import type { RootState, AppDispatch } from '../../redux/store';

const Pizza: React.FC = () => {
  const navigate = useNavigate();
  const [loadingPizza, setLoadingPizza] = useState(true);
  const isSearch = useRef(false);
  const isMounted = useRef(false);

  const dispatch = useDispatch<AppDispatch>();
  const { categoryId, sort, pageCount, searchValue } = useSelector(
    (state: RootState) => state.filter,
  );
  const { items, status } = useSelector((state: RootState) => state.pizza);

  const onChangePage = (number: number) => {
    dispatch(setPageCount(number));
  };

  const getPizza = async () => {
    setLoadingPizza(true);
    const categoryParam = categoryId > 0 ? `category=${categoryId}` : '';
    const sortParam = `sortBy=${sort.sortProperty}`;
    const search = searchValue ? `&search=${searchValue}` : '';
    try {
      dispatch(
        fetchPizzas({
          categoryParam,
          sortParam,
          search,
          pageCount,
        }) as any,
      );
    } catch (err) {
      console.error('Помилка завантаження піц', err);
    } finally {
      setLoadingPizza(false);
    }
  };

  useEffect(() => {
    if (window.location.search) {
      const params = qs.parse(window.location.search.substring(1));
      const sortObj =
        sortOptions.find((obj) => obj.sortProperty === params.sortProperty) || sortOptions[0];

      dispatch(
        setFilters({
          ...params,
          sort: sortObj,
        }) as any,
      );
      isSearch.current = true;
    }
  }, [dispatch]);

  useEffect(() => {
    window.scrollTo(0, 0);

    if (!isSearch.current) {
      getPizza();
    }

    isSearch.current = false;
  }, [categoryId, sort, searchValue, pageCount]);

  useEffect(() => {
    if (isMounted.current) {
      const queryString = qs.stringify({
        sortProperty: sort?.sortProperty || 'rating',
        categoryId,
        pageCount,
      });
      navigate(`?${queryString}`);
    }
    isMounted.current = true;
  }, [categoryId, sort, pageCount, navigate]);

  const pizzasList = Array.isArray(items)
    ? items.map((obj) => <PizzaCard key={obj.id} {...obj} />)
    : [];

  const skeletons = [...new Array(6)].map((_, index) => <Skeleton key={index} />);

  return (
    <section className="pizza">
      <div className="container">
        <div className="pizza__content">
          <div className="pizza__title">
            <h1>Усі піци</h1>
          </div>
          <div className="pizza__cart-wrapper">{status === 'loading' ? skeletons : pizzasList}</div>
        </div>
        <Paginate pageCount={pageCount} onChangePage={onChangePage} />
      </div>
    </section>
  );
};

export default Pizza;
