import { createAsyncThunk, createSlice, PayloadAction } from '@reduxjs/toolkit';
import axios from 'axios';

// Тип одной пиццы
export type PizzaItem = {
  id: string;
  title: string;
  price: number;
  imageUrl: string;
  sizes: number[];
  types: number[];
  rating: number;
};

// Тип для параметров запроса
export type FetchPizzasArgs = {
  categoryParam: string;
  sortParam: string;
  search: string;
  pageCount: number;
};

// Асинхронный thunk для загрузки пицц
export const fetchPizzas = createAsyncThunk<PizzaItem[], FetchPizzasArgs>(
  'pizza/fetchPizzasStatus',
  async (params) => {
    const { categoryParam, sortParam, search, pageCount } = params;
    const { data } = await axios.get<PizzaItem[]>(
      `https://68945a4fbe3700414e12d1e9.mockapi.io/items?page=${pageCount}&limit=4&${categoryParam}&${sortParam}${search}`,
    );
    return data;
  },
);

// Возможные статусы загрузки
export type PizzaSliceStatus = 'loading' | 'succeeded' | 'failed';

export interface PizzaSliceState {
  items: PizzaItem[];
  status: PizzaSliceStatus;
}

const initialState: PizzaSliceState = {
  items: [],
  status: 'loading',
};

const pizzaSlice = createSlice({
  name: 'pizza',
  initialState,
  reducers: {
    setItems(state, action: PayloadAction<PizzaItem[]>) {
      state.items = action.payload;
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchPizzas.pending, (state) => {
        state.status = 'loading';
        state.items = [];
      })
      .addCase(fetchPizzas.fulfilled, (state, action: PayloadAction<PizzaItem[]>) => {
        state.items = action.payload;
        state.status = 'succeeded';
      })
      .addCase(fetchPizzas.rejected, (state) => {
        state.status = 'failed';
        state.items = [];
      });
  },
});

export const { setItems } = pizzaSlice.actions;
export default pizzaSlice.reducer;
