import plus from './../../img/plus.svg';
import min from './../../img/min.svg';
import cross from './../../img/cross.svg';
import { useDispatch } from 'react-redux';
import { addItems, minuseItem, removeItems } from '../../redux/slices/cartSlice';
interface CartItemProps {
  id: string;
  title: string;
  price: number;
  imageUrl: string;
  count: number;
  type: string;
  size: number;
}
function CartItems({ id, title, price, imageUrl, count, type, size }: CartItemProps) {
  const dispatch = useDispatch();
  const onClickPlus = () => {
    dispatch(
      addItems({
        id,
        title,
        price,
        imageUrl,
        type,
        size,
        count: 1,
        types: [],
        sizes: [],
      }),
    );
  };

  const onClickMinus = () => {
    dispatch(minuseItem(id));
  };

  const onClickRemove = () => {
    dispatch(removeItems(id));
  };
  return (
    <div className="cart__card">
      <img className="pizza-img" src={imageUrl} alt="" />
      <div className="cart__title-text">
        <h3 className="cart__text">{title}</h3>
        <p className="cart__page">
          {type}, {size} см.
        </p>
      </div>

      <div className="cart__add">
        <button onClick={onClickMinus}>
          <img src={min} alt="" />
        </button>
        <p>{count}</p>
        <button onClick={onClickPlus}>
          <img src={plus} alt="" />
        </button>
      </div>
      <div className="cart__price">
        <p>{price * count} грн</p>
      </div>
      <button onClick={onClickRemove}>
        <img src={cross} alt="" />
      </button>
    </div>
  );
}

export default CartItems;
