import { CartItem } from '../redux/slices/cartSlice';
import { calcTotalPrice } from './cartTotalPrice';

export const getCartFromLS = (): { items: CartItem[]; totalPrice: number } => {
  const data = localStorage.getItem('cart');

  if (data) {
    const items: CartItem[] = JSON.parse(data);
    return {
      items,
      totalPrice: calcTotalPrice(items),
    };
  }

  return {
    items: [],
    totalPrice: 0,
  };
};
