import { useParams } from 'react-router-dom';
import axios from 'axios';
import React from 'react';
import { Link } from 'react-router-dom';

interface Pizza {
  imageUrl: string;
  title: string;
  price: number;
  ingredients: string;
}

const InfoPizza: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const [pizza, setPizza] = React.useState<Pizza | null>(null);

  React.useEffect(() => {
    async function fetchPizza() {
      try {
        const { data } = await axios.get<Pizza>(
          `https://68945a4fbe3700414e12d1e9.mockapi.io/items/${id}`,
        );
        setPizza(data);
      } catch (error) {
        console.error('Помилка завантаження піци:', error);
      }
    }

    if (id) {
      fetchPizza();
    }
  }, [id]);

  if (!pizza) {
    return <p>Loading...</p>;
  }

  return (
    <div className="pizza__items">
      <div className="container">
        <div className="wrap">
          <img src={pizza.imageUrl} alt={pizza.title} />
          <h1 className="cart__title castom">{pizza.title}</h1>
          <p className="cart__text castom__text">{pizza.ingredients}</p>
        </div>
        <Link to="/" className="cart__back-btn info">
          Повернутись назад
        </Link>
      </div>
    </div>
  );
};

export default InfoPizza;
