import React from 'react';
import { Link } from 'react-router-dom';
import cartIcon from './../../img/cartCart.svg';
import trash from './../../img/trash.svg';
import CartItems from './CartItems';
import './cart.css';
import { useDispatch, useSelector } from 'react-redux';
import { clearItems, selectCart } from '../../redux/slices/cartSlice';
import EmptyCart from './EmptyCart';

interface CartItem {
  id: string;
  title: string;
  price: number;
  imageUrl: string;
  count: number;
  type: string;
  size: number;
}

const Cart: React.FC = () => {
  const dispatch = useDispatch();
  const { items, totalPrice } = useSelector(selectCart);

  const onClickClear = () => {
    dispatch(clearItems());
  };

  // Преобразуем items в CartItem с защитой от undefined
  const cartItems: CartItem[] = items.map((item) => ({
    id: item.id,
    title: item.title,
    price: item.price,
    imageUrl: item.imageUrl,
    count: item.count,
    type: item.type,
    size: item.size,
  }));

  const totalCount = cartItems.reduce((sum, item) => sum + item.count, 0);

  if (!items.length || totalPrice === 0) {
    return <EmptyCart />;
  }

  return (
    <section className="cart">
      <div className="container container--cart">
        <div className="cart__content">
          <div className="cart__head">
            <div className="cart__head-title">
              <img src={cartIcon} alt="Корзина" />
              <h2 className="cart__title">Кошик</h2>
            </div>

            <button onClick={onClickClear} className="cart__clear">
              <img src={trash} alt="Очистити" />
              <p className="cart__clear-text">Очистити кошик</p>
            </button>
          </div>

          <div className="cart__items">
            {cartItems.map((item) => (
              <CartItems
                key={`${item.id}_${item.type}_${item.size}`}
                id={item.id}
                title={item.title}
                price={item.price}
                imageUrl={item.imageUrl}
                count={item.count}
                type={item.type}
                size={item.size}
              />
            ))}
          </div>

          <div className="cart__all">
            <div className="cart__all-item">
              <p>
                Усього піци: <span>{totalCount} шт.</span>
              </p>
            </div>
            <div className="cart__all-price">
              <p>
                Сума замовлення: <span>{totalPrice} грн</span>
              </p>
            </div>
          </div>

          <div className="cart__btn-all">
            <Link to="/" className="cart__back-btn">
              Повернутись назад
            </Link>
            <button className="cart__btn-pay">Оплатити зараз</button>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Cart;
