import { Link } from 'react-router-dom';
import cartEmpt from './../../img/cart-empty.svg';
function EmptyCart() {
  return (
    <section className="cart flex">
      <div className="container">
        <h1 className="cart__title">Кошик порожній</h1>
        <img src={cartEmpt} alt="" />

        <div className="cart__btn-all">
          <Link to="/" className="cart__back-btn">
            Повернутись назад
          </Link>
        </div>
      </div>
    </section>
  );
}

export default EmptyCart;
