import { Link, useLocation } from 'react-router-dom';
import logo from '../../img/logo.svg';
import cart from '../../img/cart.svg';
import './header.css';
import search from '../../img/search.svg';
import cross from '../../img/crossin.svg';
import React from 'react';
import debounce from 'lodash.debounce';
import { useDispatch, useSelector } from 'react-redux';
import { setSearchValue } from '../../redux/slices/filterSlice';
import type { RootState } from '../../redux/store';
import type { AppDispatch } from '../../redux/store';

const Header: React.FC = () => {
  const [value, setValue] = React.useState('');
  const inputRef = React.useRef<HTMLInputElement>(null);
  const dispatch = useDispatch<AppDispatch>();
  const location = useLocation();
  const isMounted = React.useRef(false);

  const onClickClear = () => {
    dispatch(setSearchValue(''));
    setValue('');
    inputRef.current?.focus();
  };

  const updateSearchValue = React.useMemo(
    () =>
      debounce((str: string) => {
        dispatch(setSearchValue(str));
      }, 1000),
    [dispatch],
  );

  const onChangeInput = (event: React.ChangeEvent<HTMLInputElement>) => {
    setValue(event.target.value);
    updateSearchValue(event.target.value);
  };

  const { items, totalPrice } = useSelector((state: RootState) => state.cart);
  const totalCount = items.reduce((sum, item) => sum + item.count, 0);
  React.useEffect(() => {
    if (isMounted.current) {
      const json = JSON.stringify(items);
      localStorage.setItem('cart', json);
    }
    isMounted.current = true;
  }, [items]);
  return (
    <section className="header">
      <div className="container">
        <div className="header__wrapper">
          <div className="header__logo">
            <div className="header__logo-img">
              <img src={logo} alt="Логотип" />
            </div>
            <div className="header__text">
              <h2 className="header__title">REACT PIZZA</h2>
              <p className="header__text">найсмачніша піца у всесвіті</p>
            </div>
          </div>
          {location.pathname !== '/cart' && (
            <div className="input__wrap">
              <div className="input__wraper">
                <input
                  ref={inputRef}
                  value={value}
                  onChange={onChangeInput}
                  type="text"
                  placeholder="Пошук..."
                  className="inputserch"
                />
                {value && (
                  <button type="button">
                    <img src={cross} alt="Очистити" onClick={onClickClear} />
                  </button>
                )}
              </div>
              <button type="button">
                <img src={search} alt="Пошук" />
              </button>
            </div>
          )}
          {location.pathname !== '/cart' && (
            <div className="header__cart">
              <Link to="/cart" className="header__cart-btn">
                <p className="header__price">{totalPrice} грн</p>
                <div></div>
                <img src={cart} alt="Корзина" />
                <p className="header__number">{totalCount}</p>
              </Link>
            </div>
          )}
        </div>
      </div>
    </section>
  );
};

export default Header;
