import React, { useState } from 'react';
import arrov from './../../img/arrov.svg';
import './nav.css';
import { useSelector, useDispatch } from 'react-redux';
import { setSort } from '../../redux/slices/filterSlice';
import type { RootState } from '../../redux/store';

export const sortOptions = [
  { name: 'популярності', sortProperty: 'rating' },
  { name: 'ціною', sortProperty: 'price' },
  { name: 'назвою', sortProperty: 'title' },
];

interface NavProps {
  value: number;
  onClickCategory: (index: number) => void;
}

interface SortOption {
  name: string;
  sortProperty: string;
}

const Nav: React.FC<NavProps> = ({ value, onClickCategory }) => {
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dispatch = useDispatch();
  const sort = useSelector((state: RootState) => state.filter.sort);
  const sortRef = React.useRef<HTMLDivElement>(null);

  const toggleDropdown = () => {
    setIsDropdownOpen(!isDropdownOpen);
  };

  const category = ['Усі', 'М`ясні', 'Вегетаріанська', 'Гриль', 'Гострі', 'Закриті'];

  const onClickListItem = (option: SortOption) => {
    dispatch(setSort(option));
    setIsDropdownOpen(false);
  };

  React.useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      if (
        sortRef.current &&
        !target.closest('.nav__dropdown') &&
        !target.closest('.nav__filter-span')
      ) {
        setIsDropdownOpen(false);
      }
    };

    document.body.addEventListener('click', handleClickOutside);
    return () => document.body.removeEventListener('click', handleClickOutside);
  }, []);

  return (
    <section className="nav">
      <div className="container">
        <div className="nav__wrapper">
          <div className="nav__list-wrapper">
            <ul className="nav__list-ul">
              {category.map((categoryName, i) => (
                <li
                  key={i}
                  className={`nav__list ${value === i ? 'nav__list--active' : ''}`}
                  onClick={() => onClickCategory(i)}
                >
                  <button>{categoryName}</button>
                </li>
              ))}
            </ul>
          </div>
          <div className="nav__filter">
            <img src={arrov} alt="arrow" />
            <p className="nav__filter-text">Сортування за:</p>
            <span onClick={toggleDropdown} className="nav__filter-span">
              {sort.name}
            </span>
            {isDropdownOpen && (
              <div ref={sortRef} className="nav__dropdown">
                <ul>
                  {sortOptions.map((option) => (
                    <li
                      key={option.sortProperty}
                      className={`nav__dropdown-li ${
                        sort.sortProperty === option.sortProperty ? 'nav__dropdown-li--active' : ''
                      }`}
                      onClick={() => onClickListItem(option)}
                    >
                      {option.name}
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        </div>
      </div>
    </section>
  );
};

export default Nav;
