import { createSlice, PayloadAction } from '@reduxjs/toolkit';

export type Sort = {
  name: string;
  sortProperty: string;
};

export interface FilterSliceState {
  searchValue: string;
  categoryId: number;
  pageCount: number;
  sort: Sort;
}

const initialState: FilterSliceState = {
  searchValue: '',
  categoryId: 0,
  pageCount: 1,
  sort: {
    name: 'популярності',
    sortProperty: 'rating',
  },
};

const filterSlice = createSlice({
  name: 'filter',
  initialState,
  reducers: {
    setCategoryId(state, action: PayloadAction<number>) {
      state.categoryId = action.payload;
    },

    setSearchValue(state, action: PayloadAction<string>) {
      state.searchValue = action.payload;
    },

    setSort(state, action: PayloadAction<Sort>) {
      state.sort = action.payload;
    },

    setPageCount(state, action: PayloadAction<number>) {
      state.pageCount = action.payload;
    },

    setFilters(state, action: PayloadAction<Partial<FilterSliceState>>) {
      if (action.payload.pageCount !== undefined) {
        state.pageCount = Number(action.payload.pageCount);
      }
      if (action.payload.sort) {
        state.sort = action.payload.sort;
      }
      if (action.payload.categoryId !== undefined) {
        state.categoryId = Number(action.payload.categoryId);
      }
      if (action.payload.searchValue !== undefined) {
        state.searchValue = action.payload.searchValue;
      }
    },
  },
});

export const { setCategoryId, setSort, setPageCount, setFilters, setSearchValue } =
  filterSlice.actions;
export default filterSlice.reducer;
